from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product
import heapq


def _round_amount(n, mode):
    return (n + 5000) // 10000 if mode == "half_up" else n // 10000


def _ledger(data, sequence_first, discounted_tax):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        if sequence_first:
            key = (sequence, event.get("revision", 0), position)
        else:
            key = (event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round_amount(raw * (10000 - discount), mode)
        base = net if discounted_tax else raw
        tax = _round_amount(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_01(data):
    return _ledger(data, True, False)


def _component_02(data):
    return _ledger(data, False, True)


def _component_03(data):
    return _ledger(data, True, True)


def _component_04(data):
    return _ledger(data, False, False)


def _component_05(data):
    return _ledger(data, True, False)


def _component_06(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    options = []
    for name in names:
        rows = [row for row in packages[name]
                if row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        options.append([None] + rows)

    best_vector = None
    best_result = None
    for combo in product(*options):
        selected = {name: row for name, row in zip(names, combo) if row is not None}
        if any(name not in selected or
               not low <= selected[name]["version"] <= high
               for name, (low, high) in roots.items()):
            continue

        graph = {}
        valid = True
        for name, row in selected.items():
            dependencies = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if (other not in selected or
                        not dep["min"] <= selected[other]["version"] <= dep["max"]):
                    valid = False
                    break
                dependencies.append(other)
            graph[name] = dependencies
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in selected:
                valid = False
                break
            reachable.add(name)
            stack.extend(graph[name])
        if not valid or reachable != set(selected):
            continue

        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in graph):
            continue

        vector = tuple(selected[name]["version"] if name in selected else -1
                       for name in names)
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best_result = {name: row["version"] for name, row in selected.items()}

    if best_result is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_result}


def _component_07(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in set(data.get("blocked", []))]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None

    for mask in range(1 << len(jobs)):
        if mask.bit_count() != k:
            continue
        chosen = [job for i, job in enumerate(jobs) if mask >> i & 1]
        ids = {job["id"] for job in chosen}
        if not mandatory <= ids:
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(chosen, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue

        value = sum(job["value"] for job in chosen)
        id_list = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and id_list > best_ids)):
            best_value, best_ids = value, id_list

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    required_bit = {node: 1 << i for i, node in enumerate(required)}
    full_mask = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = required_bit.get(source, 0)
    initial_state = (source, 0, initial_mask)
    distances = {initial_state: data["start"]}
    queue = [(data["start"], source, 0, initial_mask)]
    coupons = data["coupons"]
    deadline = data["deadline"]

    while queue:
        time, node, used, mask = heapq.heappop(queue)
        state = (node, used, mask)
        if distances.get(state) != time:
            continue
        if node == data["target"] and used == coupons and mask == full_mask:
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            for spend in (0, 1):
                if used + spend > coupons:
                    continue
                duration = edge["duration"]
                if spend:
                    duration = max(1, duration - edge.get("discount", 0))
                arrival = depart + duration
                if arrival > deadline:
                    continue
                dest = edge["v"]
                next_mask = mask | required_bit.get(dest, 0)
                next_state = (dest, used + spend, next_mask)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, dest, used + spend, next_mask))

    return {"arrival": None}


SOLVERS = {
